WITH flattened_attrs AS (SELECT id, customer_id, coupon_codes, attributes, attributes['device'] AS device, SIZE(items) AS num_items, SIZE(attributes) AS num_attributes, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg, AGGREGATE(items, 0.0D, (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS cart_value FROM carts) SELECT customer_id, MAX(num_items) AS max_num_items, APPROX_PERCENTILE(num_items, 0.95) AS num_items_p95 FROM flattened_attrs GROUP BY customer_id ORDER BY customer_id DESC NULLS LAST;
